def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    woman_patches = image_patch.find("woman")
    suit_patches = image_patch.find("suit")
    cake_patches = image_patch.find("cake")

    if not man_patches or not woman_patches or not suit_patches or not cake_patches:
        return image_patch

    man = max(man_patches, key=lambda m: m.overlaps_with(suit_patches[0].left, suit_patches[0].lower, suit_patches[0].right, suit_patches[0].upper))
    woman = max(woman_patches, key=lambda w: w.overlaps_with(cake_patches[0].left, cake_patches[0].lower, cake_patches[0].right, cake_patches[0].upper))

    if not man or not woman:
        return image_patch

    man_wearing_suit = any(m.overlaps_with(suit_patches[0].left, suit_patches[0].lower, suit_patches[0].right, suit_patches[0].upper) for m in man_patches)

    if not man_wearing_suit:
        return image_patch

    help_action = image_patch.llm_query(f"Is {man.name} helping {woman.name} cut their cake?", long_answer=False).strip().lower()

    if help_action == "yes":
        return man
    else:
        return image_patch

